from taf.internal.managedobject import ManagedObject
from taf.sbts.oam.coam.admin import AdminConnection as SbtsAdminConnection

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedSbtsAdminConnection(ManagedObject):
    """
    ManagedObject interface for Sbts AdminConnection.
    """

    def __init__(
            self,
            admin_connection_params,
            **kwargs):
        super(ManagedSbtsAdminConnection, self).__init__(**kwargs)
        parameter_mapping = {"host": "bts_host", "port": "bts_port", "user": "username"}
        self._admin_connection_params = {
            parameter_mapping.get(k, k): v
            for k, v in admin_connection_params.items()
            if k != "reuse"}
        self._admin_connection = None

    @property
    def admin_connection(self):
        return self._admin_connection

    def _create_admin_connection(self, admin_connection_params):
        return SbtsAdminConnection(**admin_connection_params)

    def __getattr__(self, name):
        if hasattr(self._admin_connection, name):
            return self._decorator(getattr(self._admin_connection, name))
        raise AttributeError("'{class_name!r}' object has no attribute '{name}'".format(
            class_name=self.__class__.__name__, name=name))

    def _decorator(self, func):
        def wrapped(*args, **kwargs):
            try:
                logger.debug("Calling {function_name} with arguments {args} and keyword arguments {kwargs}".
                             format(function_name=func.__name__, args=args, kwargs=kwargs))
                result = func(*args, **kwargs)
                logger.debug("{function_name} returned {result!r}".format(function_name=func.__name__, result=result))
                return result
            except Exception as e:
                logger.debug(
                    "{function_name} failed due to {exception!r}".format(function_name=func.__name__, exception=e))
                raise
        return wrapped

    def _setup(self):
        logger.debug("connecting: {admin_connection_params}".format(
            admin_connection_params=self._admin_connection_params))
        self._admin_connection = self._create_admin_connection(
            admin_connection_params=self._admin_connection_params)

    def _teardown(self):
        logger.debug("disconnecting: {admin_connection_params}".format(
            admin_connection_params=self._admin_connection_params))
        try:
            self._admin_connection.disconnect()
        except Exception as e:
            logger.debug("disconnecting failed due to {exception!r}".format(exception=e))

